          }
          if (value.idStr != "") {
            ProtoAdapter.STRING.encodeWithTag(writer, 2, value.idStr)
          }
          if (value.id != 0L) {
            ProtoAdapter.INT64.encodeWithTag(writer, 1, value.id)
          }
        }

        override fun decode(reader: ProtoReader): UserStats {
          var id: Long = 0L
          var idStr: String = ""
          var followingCount: Long = 0L
          var followerCount: Long = 0L
          var recordCount: Long = 0L
          var totalDuration: Long = 0L
          var dailyFanTicketCount: Long = 0L
          var dailyIncome: Long = 0L
          var itemCount: Long = 0L
          var favoriteItemCount: Long = 0L
          var diamondConsumedCount: Long = 0L
          var tuwenItemCount: Long = 0L
          val unknownFields = reader.forEachTag { tag ->
            when (tag) {
              1 -> id = ProtoAdapter.INT64.decode(reader)
              2 -> idStr = ProtoAdapter.STRING.decode(reader)
              3 -> followingCount = ProtoAdapter.INT64.decode(reader)
              4 -> followerCount = ProtoAdapter.INT64.decode(reader)
              5 -> recordCount = ProtoAdapter.INT64.decode(reader)
              6 -> totalDuration = ProtoAdapter.INT64.decode(reader)
              7 -> dailyFanTicketCount = ProtoAdapter.INT64.decode(reader)
              8 -> dailyIncome = ProtoAdapter.INT64.decode(reader)
              9 -> itemCount = ProtoAdapter.INT64.decode(reader)
              10 -> favoriteItemCount = ProtoAdapter.INT64.decode(reader)
              12 -> diamondConsumedCount = ProtoAdapter.INT64.decode(reader)
              13 -> tuwenItemCount = ProtoAdapter.INT64.decode(reader)
